internal sealed class QueueStore {
 internal static readonly string DirectoryRoot=Path.Combine(UpdateManager.DataRoot,"automation-v8");
 readonly object gate=new object(); readonly string root; QueueSnapshot data;string persistenceError="";readonly HashSet<int> writingSlots=new HashSet<int>();
 long edgePing,rendererPing,manualDeadline;int edgeBacklog;bool listenerEnabled,listenerCompatible;string lastNotice="";long lastNoticeAt; string edgeState="未连接 Edge 礼物页面",rendererOwner="";
 internal const int Slots=12,MaxPending=500; internal const long VideoLimit=128L*1024*1024;
 static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=64*1024*1024,RecursionLimit=64};}
 internal static long Now(){return DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();}
 internal static string S(Dictionary<string,object> d,string k){object v;return d!=null&&d.TryGetValue(k,out v)&&v!=null?Convert.ToString(v):"";}
 internal static string Hash(byte[] b){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(b)).Replace("-","").ToLowerInvariant();}
 internal static string FileHash(string p){using(var h=SHA256.Create())using(var f=File.OpenRead(p))return BitConverter.ToString(h.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
 internal static string Id(string url){Uri u;if(!Uri.TryCreate(url,UriKind.Absolute,out u)||u.Scheme!="https"||(u.Host!="www.douyin.com"&&u.Host!="douyin.com")||!System.Text.RegularExpressions.Regex.IsMatch(u.AbsolutePath,@"^/user/[A-Za-z0-9_-]{3,200}/?$"))return "";return u.AbsolutePath.TrimEnd('/').Split('/').Last();}
 internal QueueStore(string appRoot){root=appRoot;Directory.CreateDirectory(DirectoryRoot);bool existed=false;int invalid=0;var valid=new List<QueueSnapshot>();
  foreach(string name in new[]{"queue-a.json","queue-b.json"}){string path=Path.Combine(DirectoryRoot,name);if(!File.Exists(path))continue;existed=true;try{if(new FileInfo(path).Length>64L*1024*1024)throw new IOException("任务存档过大");var envelope=Json().Deserialize<Dictionary<string,object>>(File.ReadAllText(path,Encoding.UTF8));string body=S(envelope,"body");if(Hash(Encoding.UTF8.GetBytes(body))!=S(envelope,"sha256")){invalid++;continue;}var snapshot=Json().Deserialize<QueueSnapshot>(body);if(snapshot.tasks==null||snapshot.seen==null||snapshot.tasks.Count>1100||snapshot.seen.Count>20000){invalid++;continue;}valid.Add(snapshot);}catch{invalid++;}}
