  if(existed&&valid.Count==0){persistenceError="任务存档无法校验；已停止监听，请保留存档排查";data.enabled=false;}
  else if(invalid>0){data.enabled=false;Notice("一个任务快照损坏，已恢复可校验存档并暂停监听；可能缺少最近的状态，请核对任务后手动开启");}
  foreach(var t in data.tasks){if(t.status=="resolving"){t.status="pending";t.lease="";}else if(t.status=="composing"){t.status="verified";t.lease="";}else if(t.status=="playing"){t.status="ready";t.playToken="";t.error="上次播放中断，可重新播放";}if(t.status=="ready"&&(!File.Exists(Video(t))||FileHash(Video(t))!=t.videoHash)){t.status="failed";t.error="成片缓存校验失败";t.profile=null;}}
  if(persistenceError==""){BeginSession(false);if(invalid>0)Notice("一个任务快照损坏，已保留历史并暂停监听；请核对后开启");Save();}
 }
 bool Current(GiftTask t){return t.session==data.session;}
 void BeginSession(bool explicitChange){
  string previous=data.session??("legacy:"+data.stream);
  foreach(var t in data.tasks)if(String.IsNullOrEmpty(t.session))t.session=previous;
  if(data.sessions==null)data.sessions=new List<Dictionary<string,object>>();
  if(data.session!=null||data.tasks.Any(Current)||data.total>0||data.warnings>0)data.sessions.Add(new Dictionary<string,object>{{"session",previous},{"received",data.total},{"completed",data.completed},{"warnings",data.warnings},{"endedAt",Now()}});
  if(data.sessions.Count>100)data.sessions.RemoveAt(0);
  data.session=Guid.NewGuid().ToString("N");data.sessionStartedAt=Now();
  data.total=data.completed=data.failures=data.warnings=data.overflow=data.restored=0;data.seen=data.tasks.Where(t=>!String.IsNullOrEmpty(t.eventKey)).Select(t=>t.eventKey).Distinct().ToList();data.notices.Clear();lastNotice="";lastNoticeAt=0;
 }
 internal bool RenderCurrent(string id,string lease){lock(gate){var t=data.tasks.Find(x=>x.id==id);return t!=null&&Current(t)&&t.status=="composing"&&t.lease==lease;}}
 internal void Progress(GiftTask t,Dictionary<string,object> progress){lock(gate){t.renderProgress=new Dictionary<string,object>(progress);}}
 internal object Cancel(Dictionary<string,object> d){lock(gate){var t=Get(d);if(!Current(t)||!new[]{"pending","resolving","verified","composing"}.Contains(t.status))throw new IOException("此任务不在当前处理队列");QueueComposer.Cancel(t.id);FailTask(t,"用户已停止此任务；可重试，文件未删除");return new{ok=true};}}
 internal object History(){lock(gate){return new{ok=true,sessions=data.sessions.ToArray(),tasks=data.tasks.Where(t=>!Current(t)&&t.status!="completed").Take(500).Select(t=>new{t.id,t.session,t.status,t.error,t.templateName,t.slot,t.renderProgress,nickname=S(t.profile,"nickname"),giftNickname=S(t.raw,"nickname"),gift=S(t.raw,"gift")}).ToArray()};}}
 internal object Restore(Dictionary<string,object> d){lock(gate){var t=Get(d);if(Current(t))throw new IOException("任务已在当前场次");if(t.status=="ready"){if(!File.Exists(Video(t))||FileHash(Video(t))!=t.videoHash)throw new IOException("历史成片校验失败，未恢复播放");}else{t.status="pending";t.lease="";t.profile=null;t.error="";}t.session=data.session;t.updated=Now();data.restored++;Save();return new{ok=true};}}
 void Save(){if(persistenceError!="")throw new IOException(persistenceError);data.generation++;string body=Json().Serialize(data);byte[] bytes=new UTF8Encoding(false).GetBytes(Json().Serialize(new{body=body,sha256=Hash(Encoding.UTF8.GetBytes(body))}));
  string file=Path.Combine(DirectoryRoot,data.generation%2==0?"queue-a.json":"queue-b.json");try{using(var f=new FileStream(file,FileMode.Create,FileAccess.Write,FileShare.Read)){f.Write(bytes,0,bytes.Length);f.Flush(true);}}catch(Exception e){data.enabled=false;persistenceError="任务存档写入失败，已停止接收和制片："+e.Message;throw new IOException(persistenceError);}
 }
 void Notice(string s){if(s==lastNotice&&Now()-lastNoticeAt<30000)return;lastNotice=s;lastNoticeAt=Now();data.warnings++;data.notices.Add(DateTime.Now.ToString("HH:mm:ss ")+s);if(data.notices.Count>50)data.notices.RemoveAt(0);}
 void Expire(){foreach(var t in data.tasks.Where(t=>(Current(t)&&(t.status=="resolving"||t.status=="composing"&&!QueueComposer.Busy))&&t.deadline<Now()).ToArray()){FailureLogs.Write(t,t.status,"任务租约超时；未采用其他用户资料",null);t.status="failed";t.error="任务租约超时；未采用其他用户资料";t.lease="";t.profile=null;data.failures++;Save();}}
 void Prune(){var old=data.tasks.Where(t=>t.status=="completed"||t.status=="archived").OrderBy(t=>t.updated).ToArray();foreach(var t in old.Take(Math.Max(0,old.Length-200)))data.tasks.Remove(t);}
 GiftTask Get(Dictionary<string,object> d){var t=data.tasks.Find(x=>x.id==S(d,"taskId"));if(t==null)throw new IOException("任务不存在");return t;}
 GiftTask Leased(Dictionary<string,object> d,string phase){var t=Get(d);if(t.status!=phase||t.lease!=S(d,"lease")||t.deadline<Now())throw new IOException("过期或不匹配的任务绑定");return t;}
 int FreeSlot(){for(int n=0;n<Slots;n++)if(!writingSlots.Contains(n)&&!data.tasks.Any(t=>t.slot==n&&new[]{"composing","ready","playing"}.Contains(t.status)))return n;return -1;}
 internal string SlotPath(int slot,string kind){if(slot<0||slot>=Slots||!new[]{"video","profile","deco","result"}.Contains(kind))throw new IOException("缓存槽无效");string dir=Path.Combine(DirectoryRoot,"slots","s"+slot);Directory.CreateDirectory(dir);return Path.Combine(dir,kind+(kind=="profile"||kind=="deco"?".png":".mp4"));}
