 internal object State(bool details){lock(gate){Expire();return new{ok=true,enabled=data.enabled,stream=data.stream,edgeConnected=Now()-edgePing<16000,edgeState=edgeState,rendererConnected=Now()-rendererPing<16000,persistenceError=persistenceError,failureLogs=FailureLogs.State(),capacity=FreeSlot()>=0,pendingLimit=MaxPending,readyLimit=Slots,sessionId=data.session,sessionStartedAt=data.sessionStartedAt,historyCount=data.tasks.Count(t=>!Current(t)&&t.status!="completed"),statistics=new{received=data.total,restored=data.restored,completed=data.completed,failures=data.failures,warnings=data.warnings,overflow=data.overflow},notices=data.notices.ToArray(),tasks=data.tasks.Where(t=>Current(t)&&t.status!="completed"&&t.status!="archived").Select(t=>new{t.id,t.eventKey,t.status,t.created,t.updated,t.attempts,t.error,t.expectedId,t.sourceUrl,t.identityMethod,t.corrected,t.templateName,t.slot,t.renderProgress,nickname=S(t.profile,"nickname"),avatarDataUrl=details?S(t.profile,"avatarDataUrl"):"",gift=S(t.raw,"gift"),giftNickname=S(t.raw,"nickname"),count=S(t.raw,"count")}).ToArray()};}}
 internal object Config(Dictionary<string,object> d){lock(gate){if(persistenceError!="")throw new IOException(persistenceError);if(S(d,"action")=="new-stream"){if(data.tasks.Any(t=>Current(t)&&t.status=="playing")||manualDeadline>Now())throw new IOException("请等当前播放或手动合成结束，再归档场次");foreach(var t in data.tasks.Where(t=>Current(t)&&t.status=="composing").ToArray()){QueueComposer.Cancel(t.id);FailTask(t,"场次已结束，合成已停止；任务保留在历史记录");}foreach(var t in data.tasks.Where(t=>Current(t)&&t.status=="resolving")){t.status="pending";t.lease="";t.profile=null;}BeginSession(true);Save();return State(false);}object v;if(d.TryGetValue("enabled",out v)){if(v is bool&&(bool)v&&Now()-edgePing<16000&&!listenerCompatible)throw new IOException("请先加载 V8.1.5 网页助手并刷新直播平台，再开启监听");data.enabled=v is bool&&(bool)v;}Save();return State(false);}}
 internal object Heartbeat(Dictionary<string,object> d){lock(gate){Uri u;if(!Uri.TryCreate(S(d,"url"),UriKind.Absolute,out u)||u.Scheme!="https"||u.Host!="anchor.douyin.com")throw new IOException("仅接受直播服务平台页面");edgePing=Now();listenerCompatible=S(d,"captureProtocol")=="causal-v1"&&S(d,"profileProtocol")=="task-header-v3"&&S(d,"sessionProtocol")=="fresh-session-v1";edgeState=listenerCompatible?S(d,"state"):"旧网页助手已连接；请加载 V8.1.5 助手并刷新直播平台";if(!listenerCompatible&&data.enabled){data.enabled=false;Notice("已暂停旧助手监听；V8.1.5 任务与主页校验需要新版助手，并刷新平台页面");Save();}int.TryParse(S(d,"backlog"),out edgeBacklog);listenerEnabled=S(d,"listenerEnabled")=="True";if(S(d,"sessionId")==data.session&&S(d,"warning")!=""){long before=data.warnings;Notice(S(d,"warning"));object details;if(data.warnings!=before&&d.TryGetValue("warningDiagnostic",out details)&&details!=null)FailureLogs.Write(new GiftTask{id=Guid.NewGuid().ToString("N"),status="capture-warning",created=Now(),updated=Now(),raw=new Dictionary<string,object>(),sourceUrl="https://anchor.douyin.com/"},"gift-observation",S(d,"warning"),details);Save();}return new{ok=true,enabled=data.enabled,stream=data.stream,sessionId=data.session,sessionStartedAt=data.sessionStartedAt,capacity=data.tasks.Count(t=>Current(t)&&t.status!="completed"&&t.status!="archived")<MaxPending&&data.tasks.Count<1000&&data.seen.Count<20000};}}
 internal object Ingest(Dictionary<string,object> d){lock(gate){bool historical=S(d,"sessionId")!=""&&S(d,"sessionId")!=data.session;if(historical&&!data.tasks.Any(t=>t.session==S(d,"sessionId"))&&!data.sessions.Any(s=>S(s,"session")==S(d,"sessionId"))&&S(d,"sessionId")!="legacy:"+data.stream)throw new IOException("历史场次标记无法验证，未丢弃助手缓冲");if(!data.enabled&&!historical)return new{ok=true,accepted=new string[0],paused=true};if(S(d,"stream")!=data.stream)throw new IOException("监听场次不匹配");var accepted=new List<string>();object value;if(!d.TryGetValue("events",out value))throw new IOException("没有礼物记录");var collection=value as System.Collections.IEnumerable;var entries=collection==null?null:collection.Cast<object>().ToArray();if(entries==null||entries.Length>50)throw new IOException("事件批次无效");
