   if(data.tasks.Count(t=>Current(t)&&t.status!="completed"&&t.status!="archived")>=MaxPending||data.tasks.Count>=1000||data.seen.Count>=20000){data.overflow++;Notice("队列或事件标识容量已满，未接收的记录仍由助手保留；无法承诺零漏单");break;}
   var raw=new Dictionary<string,object>();bool oversized=false;foreach(string field in new[]{"nickname","profileUrl","recordId","text","gift","count","fingerprint","nodeToken","pageId","capturedSourceUrl","captureBasis","captureError"}){string text=S(e,field);int limit=field=="fingerprint"||field=="text"?4096:field=="profileUrl"||field=="capturedSourceUrl"?1024:field=="captureError"?500:256;if(text.Length>limit){oversized=true;text=text.Substring(0,limit);}raw[field]=text;}string url=S(e,"profileUrl"),basis="direct-href";if(Id(url)==""&&S(e,"captureBasis")=="causal-open"&&S(e,"nodeToken").Length==36&&S(e,"fingerprint")!=""){url=S(e,"capturedSourceUrl");basis="causal-open";}string identity=Id(url);var task=new GiftTask{id=Guid.NewGuid().ToString("N"),eventKey=key,stream=data.stream,session=historical?S(d,"sessionId"):data.session,status="pending",raw=raw,profile=null,created=Now(),updated=Now(),expectedId=identity,sourceUrl=identity==""?"":"https://www.douyin.com/user/"+identity,error="",identityMethod=identity==""?"":basis};if(S(e,"captureError")!=""){task.status="failed";task.error=S(raw,"captureError");if(!historical)data.failures++;}else if(oversized){task.status="failed";task.error="原始礼物行资料超过安全长度，未猜测或截短身份后制片；请核对身份";if(!historical)data.failures++;}if(task.status=="failed")FailureLogs.Write(task,"gift-capture",task.error,null);data.tasks.Add(task);data.seen.Add(key);if(!historical)data.total++;accepted.Add(key);
