 internal object ClaimIdentity(){lock(gate){Expire();if(!data.enabled||FreeSlot()<0||data.tasks.Any(x=>Current(x)&&(x.status=="resolving"||x.status=="verified"||x.status=="composing")))return new{ok=true,task=(object)null};var t=data.tasks.FirstOrDefault(x=>Current(x)&&x.status=="pending");if(t==null)return new{ok=true,task=(object)null};t.status="resolving";t.profileNonce="";t.lease=Guid.NewGuid().ToString("N");t.deadline=Now()+60000;t.attempts++;t.updated=Now();Save();return new{ok=true,task=new{t.id,t.lease,t.raw,t.expectedId,t.sourceUrl,t.identityMethod,t.deadline,t.attempts}};}}
 internal object BindTarget(Dictionary<string,object> d){lock(gate){var t=Leased(d,"resolving");string uid=Id(S(d,"sourceUrl"));if(uid=="")throw new IOException("没有可验证的账号标识");if(t.expectedId!=""&&uid!=t.expectedId){FailTask(t,"原始送礼目标与打开的主页账号不匹配");throw new IOException(t.error);}if(t.expectedId==""){if(S(d,"basis")!="causal-open"||S(d,"nodeToken")!=S(t.raw,"nodeToken")||S(d,"fingerprint")!=S(t.raw,"fingerprint"))throw new IOException("缺少与原始礼物记录绑定的点击证据");t.identityMethod="causal-open";}string nonce=S(d,"nonce");Guid parsed;if(!Guid.TryParseExact(nonce,"D",out parsed))throw new IOException("缺少有效的临时主页任务标记；请加载新版助手");t.profileNonce=nonce;t.expectedId=uid;t.sourceUrl="https://www.douyin.com/user/"+uid;Save();return new{ok=true,expectedId=uid};}}
 internal object Profile(Dictionary<string,object> d){GiftTask t;Dictionary<string,object> p;string lease;
  lock(gate){t=Leased(d,"resolving");lease=t.lease;object value;if(!d.TryGetValue("profile",out value)||(p=value as Dictionary<string,object>)==null)throw new IOException("用户资料不完整");if(t.expectedId==""||Id(S(p,"sourceUrl"))!=t.expectedId||S(p,"identityId")!=t.expectedId||(S(p,"canonicalId")!=""&&S(p,"canonicalId")!=t.expectedId)){FailTask(t,"主页唯一账号标识不匹配，停止制片");throw new IOException(t.error);}object proof;var evidence=p.TryGetValue("evidence",out proof)?proof as Dictionary<string,object>:null;Uri address;int stable;object meta=null;var ids=evidence!=null&&evidence.TryGetValue("metadataIds",out meta)?meta as System.Collections.IEnumerable:null;
