   if(S(p,"nickname").Trim()==""||S(p,"nickname").Length>256)throw new IOException("未读取完整昵称");if(!t.corrected&&S(t.raw,"nickname")!=""&&NicknameKey(S(t.raw,"nickname"))!=NicknameKey(S(p,"nickname"))){FailTask(t,"主页昵称与原送礼记录不一致，可能仍有旧资料或用户改名；请人工核对账号后重试");throw new IOException(t.error);}}
