 }
 internal static string NicknameKey(string name){return System.Text.RegularExpressions.Regex.Replace(name.Normalize(NormalizationForm.FormC).Replace("\uFE0E","").Replace("\uFE0F",""),@"\s+"," ").Trim();}
 internal static string DownloadAvatar(string url){Uri u;string[] allowed={"douyinpic.com","byteimg.com","ibytedtos.com","bytecdn.cn","douyincdn.com","pstatp.com","bytegoofy.com","avatars.githubusercontent.com"};if(!Uri.TryCreate(url,UriKind.Absolute,out u)||u.Scheme!="https"||u.Port!=443||u.UserInfo!=""||!allowed.Any(h=>u.Host==h||u.Host.EndsWith("."+h,StringComparison.OrdinalIgnoreCase)))throw new IOException("头像不是受支持的公开图片地址；请报告异常，未采用旧头像");ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;var req=(HttpWebRequest)WebRequest.Create(u);req.Timeout=12000;req.ReadWriteTimeout=12000;req.AllowAutoRedirect=false;req.UserAgent="BeautyWeapon/8.0";
  using(var response=(HttpWebResponse)req.GetResponse()){if((int)response.StatusCode!=200)throw new IOException("头像下载未成功");using(var input=response.GetResponseStream())using(var output=new MemoryStream()){byte[] b=new byte[32768];int n;while((n=input.Read(b,0,b.Length))>0){if(output.Length+n>1048576)throw new IOException("头像超过 1 MB");output.Write(b,0,n);}output.Position=0;using(var image=Image.FromStream(output)){if(image.Width<1||image.Height<1||image.Width>4096||image.Height>4096)throw new IOException("头像尺寸无效");using(var normalized=new Bitmap(image,Math.Min(256,image.Width),Math.Min(256,image.Height)))using(var bytes=new MemoryStream()){normalized.Save(bytes,System.Drawing.Imaging.ImageFormat.Png);return "data:image/png;base64,"+Convert.ToBase64String(bytes.ToArray());}}}}
 }
