 internal object DiagnosticReport(Dictionary<string,object> d){lock(gate){var t=Get(d);int attempt;if(!Int32.TryParse(S(d,"attempt"),out attempt)||attempt<1||attempt>t.attempts)return new{ok=true,ignored=true};if(t.diagnosticAttempts==null)t.diagnosticAttempts=new List<int>();if(t.diagnosticAttempts.Contains(attempt))return new{ok=true,duplicate=true};object details;d.TryGetValue("diagnostic",out details);string path=FailureLogs.Write(t,attempt==t.attempts?"identity-details":"delayed-previous-attempt-details",S(d,"error")==""?t.error:S(d,"error"),details);if(path=="")throw new IOException("桌面失败日志保存失败："+FailureLogs.LastError);t.diagnosticAttempt=attempt;t.diagnosticAttempts.Add(attempt);if(t.diagnosticAttempts.Count>20)t.diagnosticAttempts.RemoveAt(0);Save();return new{ok=true};}}
 internal object ExportFailureLogs(){lock(gate){int count=0;foreach(var t in data.tasks.Where(x=>x.status=="failed")){if(FailureLogs.Write(t,"historical-task",t.error,null,true)=="")throw new IOException(FailureLogs.LastError);count++;}return new{ok=true,count=count,folder=FailureLogs.Folder};}}
 internal object Archive(Dictionary<string,object> d){lock(gate){var t=Get(d);if(t.status!="failed")throw new IOException("仅可归档已失败任务");t.status="archived";t.profile=null;t.updated=Now();Prune();Save();return new{ok=true};}}
 internal object Retry(Dictionary<string,object> d){lock(gate){var t=Get(d);if(t.status!="failed")throw new IOException("仅异常任务可重试");if(!Current(t))throw new IOException("请先从历史记录恢复此任务");string corrected=S(d,"sourceUrl");if(corrected!=""){string uid=Id(corrected);if(uid=="")throw new IOException("请输入完整抖音用户主页地址");t.expectedId=uid;t.sourceUrl="https://www.douyin.com/user/"+uid;t.identityMethod="manual-correction";t.corrected=true;}
  object reset;if(d.TryGetValue("resetTemplate",out reset)&&reset is bool&&(bool)reset){t.templateId="";t.templateName="";}t.status="pending";t.profile=null;t.error="";t.lease="";t.updated=Now();Save();return new{ok=true};}}
 internal object ClaimRender(Dictionary<string,object> d){lock(gate){Expire();rendererPing=Now();string owner=S(d,"owner");if(owner.Length!=32)throw new IOException("制片器标识无效");if(persistenceError!=""||QueueComposer.Busy||data.tasks.Any(x=>x.status=="composing")||manualDeadline>Now()||FreeSlot()<0)return new{ok=true,task=(object)null};var t=data.tasks.FirstOrDefault(x=>Current(x)&&x.status=="verified");if(t==null||QueueComposer.InFlight(root))return new{ok=true,task=(object)null};rendererOwner=owner;t.slot=FreeSlot();t.status="composing";t.lease=Guid.NewGuid().ToString("N");t.deadline=Now()+360000;t.renderProgress=new Dictionary<string,object>{{"stage","准备模板"},{"startedAt",Now()}};t.updated=Now();Save();return new{ok=true,task=new{t.id,t.lease,t.profile,t.expectedId,t.templateId,t.templateName,t.slot,t.deadline}};}}
 internal object SetTemplate(Dictionary<string,object> d){lock(gate){var t=Leased(d,"composing");if(t.templateId!=""&&t.templateId!=null&&t.templateId!=S(d,"templateId"))throw new IOException("重试不能偷偷换模板");t.templateId=S(d,"templateId");t.templateName=S(d,"templateName");Save();return new{ok=true};}}
 internal void Upload(Dictionary<string,object> d,string kind,Stream input,long length){GiftTask t;string path;int slot;lock(gate){t=Leased(d,"composing");if(!new[]{"video","profile","deco"}.Contains(kind))throw new IOException("仅可写入任务素材");if(t.renderMeta!=null&&S(t.renderMeta,"lease")==t.lease)throw new IOException("合成已经开始，禁止改变素材");slot=t.slot;path=SlotPath(slot,kind);if(!writingSlots.Add(slot))throw new IOException("任务素材正在写入，禁止同时更改");}try{long limit=kind=="video"?VideoLimit:8*1024*1024;if(length<=0||length>limit)throw new IOException("素材超出大小限制");using(var output=new FileStream(path,FileMode.Create,FileAccess.Write,FileShare.None)){byte[] b=new byte[131072];long count=0;int n;while((n=input.Read(b,0,b.Length))>0){count+=n;if(count>limit)throw new IOException("素材超过限制");output.Write(b,0,n);}if(count!=length)throw new IOException("素材被截断");output.Flush(true);}lock(gate)Leased(d,"composing");}finally{lock(gate)writingSlots.Remove(slot);}}
 internal object Compose(Dictionary<string,object> d){GiftTask t;lock(gate){t=Leased(d,"composing");if(writingSlots.Contains(t.slot))throw new IOException("素材尚在写入，未启动合成");if(t.renderMeta!=null&&S(t.renderMeta,"lease")==t.lease)throw new IOException("合成已启动");t.renderMeta=d;Save();}
  ThreadPool.QueueUserWorkItem(_=>{try{QueueComposer.Render(root,this,t,d);lock(gate){if(t.status!="composing"||t.lease!=S(d,"lease"))return;t.videoHash=FileHash(Video(t));t.status="ready";t.updated=Now();t.lease="";Save();}}catch(Exception e){lock(gate)if(t.status=="composing"&&t.lease==S(d,"lease")){try{FailTask(t,e.Message);}catch(IOException){/* Save already records the persistent-storage failure; do not crash the streaming app. */}}}});return new{ok=true};}
 void CheckManualCache(){string cache=Path.Combine(root,"components","cache");if(!Directory.Exists(cache))return;var dirs=new Queue<string>();dirs.Enqueue(cache);long size=0;int entries=0;while(dirs.Count>0){string dir=dirs.Dequeue();foreach(string file in Directory.EnumerateFileSystemEntries(dir)){var a=File.GetAttributes(file);if((a&FileAttributes.ReparsePoint)!=0)throw new IOException("手动合成缓存包含链接目录，已停止写入；请核对缓存目录");if(++entries>2000)throw new IOException("旧手动合成缓存记录已达上限，请先自行备份整理；自动队列使用固定缓存槽，不会删除用户文件");if((a&FileAttributes.Directory)!=0)dirs.Enqueue(file);else{size+=new FileInfo(file).Length;if(size>=2L*1024*1024*1024)throw new IOException("旧手动合成缓存已达 2 GB，已停止继续积累；请先自行备份整理，不会自动删除任何文件");}}}}
 internal object Manual(Dictionary<string,object> d){lock(gate){if(S(d,"action")=="release"){manualDeadline=0;return new{ok=true};}if(manualDeadline>Now()||QueueComposer.InFlight(root)||data.tasks.Any(x=>x.status=="composing"))throw new IOException("已有视频正在合成，请等待当前任务完成");CheckManualCache();manualDeadline=Now()+240000;return new{ok=true};}}
 internal object Play(Dictionary<string,object> d){lock(gate){if(data.tasks.Any(x=>x.status=="playing"))throw new IOException("已有任务正在播放");var t=S(d,"taskId")==""?data.tasks.FirstOrDefault(x=>Current(x)&&x.status=="ready"):Get(d);if(t==null||!Current(t)||t.status!="ready")throw new IOException("没有已就绪的任务");if(FileHash(Video(t))!=t.videoHash){FailTask(t,"成片校验失败");throw new IOException(t.error);}t.status="playing";t.playToken=Guid.NewGuid().ToString("N");t.updated=Now();Save();return new{ok=true,task=new{t.id,t.playToken,t.profile,t.templateName,t.videoHash}};}}
 internal object End(Dictionary<string,object> d){lock(gate){var t=Get(d);if(t.status!="playing"||t.playToken!=S(d,"playToken"))throw new IOException("播放任务绑定不一致");object complete;bool done=d.TryGetValue("completed",out complete)&&complete is bool&&(bool)complete;t.status=done?"completed":"ready";t.playToken="";t.updated=Now();if(done){data.completed++;t.profile=null;}Prune();Save();return new{ok=true};}}
 internal void SendVideo(HttpListenerContext c,string id){string file;lock(gate){var t=data.tasks.Find(x=>x.id==id);if(t==null||!(t.status=="ready"||t.status=="playing"))throw new IOException("视频不在待播队列");file=Video(t);}using(var f=File.OpenRead(file)){long start=0,end=f.Length-1;string range=c.Request.Headers["Range"];if(!String.IsNullOrEmpty(range)){var m=System.Text.RegularExpressions.Regex.Match(range,@"^bytes=(\d+)-(\d*)$");if(!m.Success)throw new IOException("Range 无效");start=long.Parse(m.Groups[1].Value);if(m.Groups[2].Value!="")end=Math.Min(end,long.Parse(m.Groups[2].Value));if(start>end)throw new IOException("Range 越界");c.Response.StatusCode=206;c.Response.Headers["Content-Range"]="bytes "+start+"-"+end+"/"+f.Length;}c.Response.ContentType="video/mp4";c.Response.Headers["Accept-Ranges"]="bytes";c.Response.ContentLength64=end-start+1;f.Position=start;byte[] b=new byte[131072];long left=end-start+1;while(left>0){int n=f.Read(b,0,(int)Math.Min(b.Length,left));if(n==0)break;c.Response.OutputStream.Write(b,0,n);left-=n;}c.Response.Close();}}
}



